<script setup lang="ts">
import { computed, ref } from 'vue';
import type { Mutable } from '../adapters/editing.js';
import type { ActionDto, HttpDto, Scalar } from '../types/wire.js';
import { manual } from '../stores/manual.js';
const props = defineProps<{ http: Mutable<HttpDto>; action?: ActionDto; observe?: boolean }>();
const rows = computed(() => Object.entries(props.http.body ?? {}));
const newKey = ref('');
const keyReason = computed(() => props.http.method === 'GET' ? 'GET не поддерживает тело запроса.' : !newKey.value.trim() ? 'Введите имя нового поля JSON.' : Object.hasOwn(props.http.body ?? {}, newKey.value.trim()) ? 'Такое поле уже существует. Измените его значение выше или укажите другое имя.' : '');
function addKey() { if (!keyReason.value) { value(newKey.value.trim(), false); newKey.value = ''; } }
function value(key: string, value: Scalar) { (props.http.body ??= {})[key] = value; }
function type(key: string, type: string) { value(key, type === 'boolean' ? false : type === 'number' ? 0 : ''); }
</script>
<template><div class="form-grid"><label>Метод<select v-model="http.method" :disabled="observe"><option v-for="method in ['POST', 'PUT', 'PATCH', 'DELETE', 'GET']" :key="method">{{ method }}</option></select></label><label v-if="http.url !== undefined">Legacy URL<input v-model="http.url" required></label><label v-else>Путь *<input v-model="http.path" required><small class="field-example">Пример: /relay/1 — укажите путь из API устройства.</small></label></div><p v-if="http.method === 'GET' && !observe" class="notice">GET здесь выполняет действие оборудования. Это не проверка доступности.</p>
    <template v-if="!observe && (http.method !== 'GET' || Object.keys(http.body ?? {}).length || http.argument)"><h4>Тело запроса · JSON</h4><div v-for="[key, v] in rows" :key="key" class="body-row"><strong>{{ key }}</strong><label>Тип<select :value="typeof v" @change="type(key, ($event.target as HTMLSelectElement).value)"><option value="boolean">Да / Нет</option><option value="number">Число</option><option value="string">Текст</option></select></label><label>Значение<select v-if="typeof v === 'boolean'" :value="String(v)" @change="value(key, ($event.target as HTMLSelectElement).value === 'true')"><option value="true">Да</option><option value="false">Нет</option></select><input v-else :type="typeof v === 'number' ? 'number' : 'text'" step="any" :value="v" @input="value(key, typeof v === 'number' ? Number(($event.target as HTMLInputElement).value) : ($event.target as HTMLInputElement).value)"></label><button type="button" @click="delete http.body![key]">Удалить поле</button></div><div class="inline-actions"><label>Новое поле JSON<input v-model="newKey"><small class="field-example">Пример: on</small></label><small class="json-key-reason" v-if="keyReason">{{ keyReason }}</small><button type="button" :disabled="!!keyReason" @click="addKey">Добавить поле JSON</button></div><details><summary>Точный JSON</summary><pre>{{ JSON.stringify(http.body ?? {}, null, 2) }}</pre></details></template>
    <details :open="manual.advanced.value"><summary>Дополнительно: HTTP contract</summary><div class="form-grid"><label>Ожидаемый HTTP status<input v-model.number="http.expected_status" type="number" min="0" max="299"><small>0 — любой 2xx</small></label><label>Timeout override, мс<input v-model.number="http.timeout_ms" type="number" min="0" max="10000"><small>0 — timeout подключения</small></label><label>Content-Type<input v-model="http.content_type" required></label><label v-if="action?.parameters.length">Параметр в теле запроса<select v-model="http.argument"><option :value="undefined">Не передавать</option><option v-for="parameter in action.parameters" :key="parameter.id" :value="parameter.id">{{ parameter.name }} → {{ parameter.id }}</option></select><small>Backend передаёт один объявленный параметр под его ключом.</small></label></div><p>Поддерживаются только non-secret Accept / X-* headers.</p><div v-for="(_, key) in http.headers" :key="key" class="inline-actions"><label>{{ key }}<input v-model="http.headers![key]"></label><button type="button" @click="delete http.headers![key]">Удалить header</button></div><button type="button" @click="(http.headers ??= {})['Accept'] = 'application/json'">Добавить Accept</button><label>Новый X-* header<input @change="(http.headers ??= {})[($event.target as HTMLInputElement).value] = ''" ><small class="field-example">Пример: X-Device-Mode</small></label><details><summary>Все поля mapping (сохранённые)</summary><pre>{{ JSON.stringify(http, null, 2) }}</pre></details></details>
</template>
